latestCypherQueries.query:
// 1. Ambil semua node (atau filter berdasarkan label, misal :Materi)
MATCH (n)
// 2. Hitung total entitas dan entitas yang memiliki deskripsi
WITH count(n) AS totalEntities,
     sum(CASE WHEN n.description IS NOT NULL AND n.description <> "" THEN 1 ELSE 0 END) AS entitiesWithDescription
// 3. Hitung rasio DC
RETURN totalEntities AS total_E,
       entitiesWithDescription AS entities_with_desc,
       1.0 * entitiesWithDescription / totalEntities AS description_completeness

