latestCypherQueries.query:
// 1. Ambil semua tipe relasi unik yang digunakan di dalam graf
CALL db.relationshipTypes() YIELD relationshipType
WITH count(relationshipType) AS totalUsedTypes

// 2. Jika Anda memiliki daftar tipe relasi target di ontologi (misal 10 jenis)
// Bandingkan jumlah yang terpakai dengan target tersebut
WITH totalUsedTypes, 10.0 AS targetTypesInOntology
RETURN totalUsedTypes AS used,
       targetTypesInOntology AS available,
       totalUsedTypes / targetTypesInOntology AS typed_relation_ratio
